// Build payload for prompt_1
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json || {};

const PROMPT_KEY   = "prompt_1";
const CONTEXT_KEYS = ["title_keyword", "high_end_products"];
const OUTPUT_KEYS  = [];
const STAGE_ID     = "prompt_1";
const USE_SEARCH   = false;
const MAX_TURNS    = 12;

const read = (key) => {
  const v = item[key] ?? staticData[key] ?? '';
  return (v === undefined || v === null) ? '' : String(v);
};

const systemContent = read(PROMPT_KEY);
if (!systemContent.trim()) {
  throw new Error(STAGE_ID + ': prompt "' + PROMPT_KEY + '" is empty. Run the first '
    + 'cycle so the prompt sheet loads into workflow static data.');
}

// Upstream outputs are required input. Empty means the previous stage did not
// store its result, which is the bug that made every rewrite stage run blind.
const parts = [];
for (const key of CONTEXT_KEYS) {
  const v = read(key);
  if (v.trim() !== '') parts.push(key + ':\n' + v);
}
for (const key of OUTPUT_KEYS) {
  const v = read(key);
  if (!v.trim()) {
    throw new Error(STAGE_ID + ': required upstream output "' + key + '" is empty.');
  }
  parts.push(key + ':\n' + v);
}

return [{ json: {
  ...item,
  systemContent,
  userContent: parts.join('\n\n'),
  stageId: STAGE_ID,
  rowNumber: Number(staticData.current_processing_row || 2),
  useWebSearch: USE_SEARCH,
  maxTurns: MAX_TURNS
} }];

// Store output_3_1 from the GPT/Codex CLI server
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json || {};
const OUTPUT_KEY = "output_3_1";
const STAGE_ID   = "output_3_1";

if (item.paused === true) {
  throw new Error(STAGE_ID + ': PAUSED — GPT/Codex CLI usage limit reached. '
    + 'No API fallback was used and nothing was billed. Wait for the limit to reset, '
    + 'delete PAUSED.flag next to claude_agent_server.py, then re-run this workflow. '
    + 'Completed stages replay from checkpoint and are not regenerated.');
}
if (item.success === false) {
  throw new Error(STAGE_ID + ': GPT/Codex CLI server error — ' + (item.error || 'unknown'));
}

const text = String(item.output || '').trim();
if (!text) {
  throw new Error(STAGE_ID + ': server returned success with an empty output.');
}

staticData[OUTPUT_KEY] = text;

const titleKeyword = staticData.title_keyword || item.title_keyword || '';
const result = {
  ...item,
  [OUTPUT_KEY]: text,
  doc_file_id: staticData.doc_file_id || item.doc_file_id || '',
  title_keyword: titleKeyword,
  high_end_products: staticData.high_end_products || item.high_end_products || '',
  mid_and_afford_products: staticData.mid_and_afford_products || item.mid_and_afford_products || ''
};

return [{ json: result }];

