// Extract doc_file_id and store in global static data.
// Also pass output_3_2 forward so it can be inserted into the newly created Google Doc.
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json || {};
const docId = item.documentId || item.id || item.document_id || item.documentIdFromGoogle || '';

staticData.doc_file_id = docId;

